// Saturating 4-bit up/down counter.
module counter (
    input  logic       clk,
    input  logic       rst_n,
    input  logic       up,
    input  logic       down,
    output logic [3:0] count
);
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            count <= 4'd0;
        end else if (up && !down && count != 4'hF) begin
            count <= count + 4'd1;
        end else if (down && !up && count != 4'd0) begin
            count <= count - 4'd1;
        end
    end

`ifdef FORMAL
