    if (f_fsyn_cycles != 8'd255) f_fsyn_cycles <= f_fsyn_cycles + 1'b1;
  end
  // reset assumption: rst_n held active for 1 cycle(s) from step 0
  initial assume(!rst_n);
  // a_counter_inc: assert property (p_counter_inc)
